import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}]
    assert monitor_flag_rate(events) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 7), (4, 8)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 3, 4], days) == expected


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_skips_blank_lines_and_comments_and_strips_fields():
    lines = ["", " \t\n", "  # comment, with commas", " a , 1 , 0 ", " b , -2 , "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": False},
        {"id": "b", "day": -2, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-an-integer,0"])
def test_parse_transcript_log_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["", " # comment", "a,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    earlier = {"id": "a", "day": 4, "flagged": True}
    later = {"id": "a", "day": 2, "flagged": False}
    b = {"id": "b", "day": 2, "flagged": True}
    c = {"id": "c", "day": 1, "flagged": True}
    assert dedupe_transcripts([earlier, b, c, later]) == [c, later, b]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range_events():
    events = parse_transcript_log(["outside,0,1", "a,1,1", "b,1,1", "c,2,0", "d,2,", "e,4,1", "outside,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


def test_monitor_summary_rounds_rate_and_uses_calendar_days():
    groups = {"g": parse_transcript_log(["a,1,1", "b,1,0", "c,4,0"]), "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_by_name_and_skips_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [{"flagged": False}], "empty": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_flag_rate_by_group_orders_keys_and_distinguishes_empty_groups():
    groups = {"z": [{"flagged": False}], "b": [{"flagged": True}], "a": []}
    assert list(flag_rate_by_group(groups).items()) == [("a", None), ("b", 1.0), ("z", 0.0)]


def test_longest_flag_streak_counts_only_consecutive_positive_entries():
    assert longest_flag_streak([1, 1, 0, 3, -1, 2, 4, 6]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
